INSERT INTO `faq_translations` VALUES (1,1,'en','How should I choose between Selenium ACE and Omega products?','<p>Selenium ACE focuses on antioxidant support; Omega-3/6 supports heart, brain, and eye health. Your pharmacist or physician can advise which fits your needs.</p>'),(2,1,'ar','كيف أختار بين منتجات Selenium ACE و Omega?','<p>يركز سيلينيوم ACE على دعم مضادات الأكسدة؛ بينما يدعم أوميغا 3/6 صحة القلب والدماغ والعين. يمكن للصيدلي أو الطبيب أن ينصحك بالخيار الأنسب لاحتياجاتك.</p>'),(3,2,'en','How should I choose between Selenium ACE and Omega products?','<p>كيف أختار بين منتجات Selenium ACE و Omega؟</p>'),(4,2,'ar','كيف أختار بين منتجات Selenium ACE و Omega?','<p>يركز سيلينيوم ACE على دعم مضادات الأكسدة؛ بينما يدعم أوميغا 3/6 صحة القلب والدماغ والعين. يمكن للصيدلي أو الطبيب أن ينصحك بالخيار الأنسب لاحتياجاتك.</p>'),(5,3,'en','How should I choose between Selenium ACE and Omega products?','<p>How should I choose between Selenium ACE and Omega products?</p>'),(6,3,'ar','How should I choose between Selenium ACE and Omega products?','<p>How should I choose between Selenium ACE and Omega products?</p>'),(7,4,'en','How should I choose between Selenium ACE and Omega products?','<p>How should I choose between Selenium ACE and Omega products?</p>'),(8,4,'ar','كيف أختار بين منتجات Selenium ACE و Omega?','<p>كيف أختار بين منتجات Selenium ACE و Omega?</p>');
