--
-- Table structure for table `order_extra_details`
--

DROP TABLE IF EXISTS `order_extra_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_extra_details` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned DEFAULT NULL,
  `ship_to_me` tinyint(1) DEFAULT '0' COMMENT ' 1 = yes   ,  0 = no  ',
  `greeting_card` text COLLATE utf8mb4_unicode_ci,
  `extra_instructions` text COLLATE utf8mb4_unicode_ci,
  `know_receipent_address` tinyint(1) DEFAULT '1' COMMENT ' [1 = yes   ,  0 = no]   it is shown only when the ship to me column is zero ',
  `same_day` tinyint(1) DEFAULT '1' COMMENT ' [1 = yes   ,  0 = no]   ',
  `delivery_date` timestamp NULL DEFAULT NULL,
  `specific_time_slot_status` tinyint(1) DEFAULT '0' COMMENT ' [1 = yes   ,  0 = no]   ',
  `specific_time` time DEFAULT NULL COMMENT '  it is set only when specific_time_slot_status is set to 1  ',
  `delivery_place` tinyint(1) DEFAULT '1' COMMENT ' [1 = home   ,  0 = office]   ',
  `hide_my_name_status` tinyint(1) DEFAULT '0' COMMENT ' [1 = yes hide it  ,  0 = no show it]   ',
  `st_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipping_cost` double(14,2) DEFAULT NULL,
  `status` tinyint DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `order_extra_details_order_id_foreign` (`order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=142 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

