INSERT INTO `reviews` VALUES (6,'App\\Models\\Product',1,'good',4,0,0,'basma customer',NULL,1,'2024-11-30 06:41:18','2024-11-03 12:40:45','2024-11-30 06:41:18','17306448450.jpg'),(18,NULL,NULL,'أنا ذوقي وحش جدًا في الورد ومكنتش عارف أختار نوع وأقرر حاجة معينة بس بصراحة أنا جربت ذوقهم واخترت بوكيه أحمر مع أبيض وأنا أول ما شوفته حسيت إني أول مرة أجيب هدية حلوة زي دي، وتوصيلهم كان سريع وخدمة ممتازة بصراحة',NULL,1,1,'Farouk',NULL,1,NULL,'2024-11-13 11:31:26','2024-12-24 06:09:19','17350313590.jpeg'),(19,NULL,NULL,'The flowers were stunning! The arrangement was elegant and unique, and the delivery was on time. I highly recommend them',NULL,1,1,'Samy Alaa',1,1,'2025-09-10 05:31:26','2024-11-30 05:21:16','2025-09-10 05:31:26','17350313870.jpeg'),(20,NULL,NULL,'<p>test</p>',NULL,1,1,'test',1,1,'2024-11-30 06:41:18','2024-11-30 05:21:34','2024-11-30 06:41:18','17329548940.jpeg'),(21,NULL,NULL,'أجمل بوكيه قدمته هدية شوفته في حياتي، تسليم سريع وزي ما طلبته بالظبط. أكيد هتعامل معاهم تاني',NULL,1,1,'Karim',NULL,1,NULL,'2024-11-30 06:31:09','2024-12-24 06:10:08','17350314080.jpeg'),(22,NULL,NULL,'بجد وردهم حلو اوي، الباكدج كان تحفة وكل الورد كان فريش وريحته حلوة. خدمة ممتازة وفعلاً حسيت إنهم بيهتموا بكل تفاصيل الطلب',NULL,0,1,'Amira Younes',NULL,1,NULL,'2024-11-30 06:32:15','2025-10-18 12:15:40','17329592660.png'),(23,NULL,NULL,'this is perfect flower store in quality,delivary and everything',NULL,1,1,'maya',1,1,'2025-05-11 04:50:37','2025-04-22 07:56:35','2025-05-11 04:50:37',NULL),(24,NULL,NULL,'بجد وردهم حلو اوي، الباكدج كان تحفة وكل الورد كان فريش وريحته حلوة. خدمة ممتازة وفعلاً حسيت إنهم بيهتموا بكل تفاصيل الطلب',NULL,1,1,'Islam osman',1,1,NULL,'2025-06-25 05:58:10','2025-09-10 05:45:48','1757493948_0.png'),(25,'App\\Models\\Product',278,'Quibusdam debitis al',5,0,0,'Kyla Frank',NULL,NULL,NULL,'2025-09-12 11:23:07','2025-09-12 11:23:07',NULL),(26,'App\\Models\\Product',278,'Quibusdam debitis al',5,0,0,'Kyla Frank',NULL,NULL,NULL,'2025-09-12 11:23:38','2025-09-12 11:23:38',NU